{"status": "proposed", "agent": "implementer", "role": "author", "executor": "claude-code", "summary": "Fixed the Enter-key conflict where the global keydown handler unconditionally called computeEquals on Enter, clobbering the click-driven action of a focused on-screen button (e.g. Backspace) that also activates via Enter. Added an exported shouldDeferToButtonActivation(target, key) helper that detects when a BUTTON element is focused and the key is Enter or Space (native button-activation keys), and the global keydown listener now skips handleKey in that case, letting the button's own click handler run its intended action. Added regression tests covering the helper directly.", "proposedPatches": [{"baseCommit": "7d5273c2f325865f3c03bfd8b57cda6e60f498d8", "files": [{"path": "src/calculator.js", "action": "modify", "content": "'use strict';\n\n// Keyboard mapping (RQ-012 / AC-012..AC-015):\n//   Digit keys '0'-'9' and '.' behave exactly like their on-screen buttons.\n//   '+' and '-' map to the addition and subtraction operators.\n//   '*', 'x', and 'X' are all treated as equivalents to the × (multiply) operator.\n//   '/' is treated as the equivalent to the ÷ (divide) operator.\n//   'Enter' and '=' trigger the same computation as the equals control.\n//   'Backspace' triggers the same behavior as the backspace/delete control.\n//   'Escape' triggers the same behavior as the clear (C) control.\n\nfunction createState() {\n  return {\n    entry: '0',\n    previous: null,\n    operator: null,\n    overwrite: false,\n    error: false,\n  };\n}\n\nfunction formatNumber(num) {\n  if (!isFinite(num)) {\n    return 'Error';\n  }\n  const rounded = Math.round(num * 1e10) / 1e10;\n  return String(rounded);\n}\n\nfunction calculate(a, b, operator) {\n  switch (operator) {\n    case '+':\n      return a + b;\n    case '-':\n      return a - b;\n    case '×':\n      return a * b;\n    case '÷':\n      if (b === 0) {\n        return null;\n      }\n      return a / b;\n    default:\n      return b;\n  }\n}\n\nfunction inputDigit(state, digit) {\n  if (state.error) {\n    clearState(state);\n  }\n  if (state.overwrite) {\n    state.entry = digit;\n    state.overwrite = false;\n  } else if (state.entry === '0') {\n    state.entry = digit;\n  } else {\n    state.entry += digit;\n  }\n  return state;\n}\n\nfunction inputDecimal(state) {\n  if (state.error) {\n    clearState(state);\n  }\n  if (state.overwrite) {\n    state.entry = '0.';\n    state.overwrite = false;\n    return state;\n  }\n  if (!state.entry.includes('.')) {\n    state.entry += '.';\n  }\n  return state;\n}\n\nfunction clearState(state) {\n  state.entry = '0';\n  state.previous = null;\n  state.operator = null;\n  state.overwrite = false;\n  state.error = false;\n  return state;\n}\n\nfunction backspace(state) {\n  if (state.error) {\n    clearState(state);\n    return state;\n  }\n  if (state.overwrite) {\n    return state;\n  }\n  state.entry = state.entry.length > 1 ? state.entry.slice(0, -1) : '0';\n  return state;\n}\n\nfunction chooseOperator(state, operator) {\n  if (state.error) {\n    clearState(state);\n  }\n  const current = parseFloat(state.entry);\n  if (state.operator !== null && !state.overwrite) {\n    const result = calculate(state.previous, current, state.operator);\n    if (result === null) {\n      state.entry = 'Error';\n      state.error = true;\n      state.previous = null;\n      state.operator = null;\n      state.overwrite = true;\n      return state;\n    }\n    state.previous = result;\n    state.entry = formatNumber(result);\n  } else {\n    state.previous = current;\n  }\n  state.operator = operator;\n  state.overwrite = true;\n  return state;\n}\n\nfunction computeEquals(state) {\n  if (state.operator === null || state.previous === null) {\n    return state;\n  }\n  const current = parseFloat(state.entry);\n  const result = calculate(state.previous, current, state.operator);\n  if (result === null) {\n    state.entry = 'Error';\n    state.error = true;\n  } else {\n    state.entry = formatNumber(result);\n    state.error = false;\n  }\n  state.previous = null;\n  state.operator = null;\n  state.overwrite = true;\n  return state;\n}\n\nfunction getDisplayValue(state) {\n  return state.entry;\n}\n\nfunction mapKeyToOperator(key) {\n  if (key === '+') return '+';\n  if (key === '-') return '-';\n  if (key === '*' || key === 'x' || key === 'X') return '×';\n  if (key === '/') return '÷';\n  return null;\n}\n\nfunction handleKey(state, key) {\n  if (/^[0-9]$/.test(key)) {\n    return inputDigit(state, key);\n  }\n  if (key === '.') {\n    return inputDecimal(state);\n  }\n  if (key === 'Enter' || key === '=') {\n    return computeEquals(state);\n  }\n  if (key === 'Backspace') {\n    return backspace(state);\n  }\n  if (key === 'Escape') {\n    return clearState(state);\n  }\n  const operator = mapKeyToOperator(key);\n  if (operator) {\n    return chooseOperator(state, operator);\n  }\n  return state;\n}\n\n// Buttons natively activate (fire a click event) on Enter and Space when\n// focused. If the global keydown handler also ran handleKey for those keys,\n// a focused button's own click-driven action would run immediately after\n// computeEquals/clearState had already mutated state (e.g. tabbing to the\n// Backspace button and pressing Enter would first collapse the pending\n// calculation via computeEquals, silently discarding the intended\n// backspace). Defer to the button's own click handler in that case instead\n// of also processing the key globally.\nfunction shouldDeferToButtonActivation(target, key) {\n  return (key === 'Enter' || key === ' ') && !!target && target.tagName === 'BUTTON';\n}\n\nconst THEME_STORAGE_KEY = 'calculator-theme';\n\nfunction getStoredTheme(storage) {\n  try {\n    return storage.getItem(THEME_STORAGE_KEY);\n  } catch (e) {\n    return null;\n  }\n}\n\nfunction applyTheme(doc, theme) {\n  doc.documentElement.setAttribute('data-theme', theme);\n}\n\nfunction setTheme(doc, storage, theme) {\n  applyTheme(doc, theme);\n  try {\n    storage.setItem(THEME_STORAGE_KEY, theme);\n  } catch (e) {\n    // Ignore storage failures (e.g. disabled storage); theme still applies for this session.\n  }\n}\n\nfunction toggleTheme(doc, storage) {\n  const current = doc.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';\n  const next = current === 'dark' ? 'light' : 'dark';\n  setTheme(doc, storage, next);\n  return next;\n}\n\nfunction initTheme(doc, storage) {\n  const stored = getStoredTheme(storage);\n  const theme = stored === 'dark' || stored === 'light' ? stored : 'light';\n  applyTheme(doc, theme);\n  return theme;\n}\n\nif (typeof document !== 'undefined') {\n  (function initApp() {\n    const state = createState();\n    const displayEl = document.getElementById('display');\n    const themeToggleEl = document.getElementById('theme-toggle');\n\n    function render() {\n      displayEl.textContent = getDisplayValue(state);\n    }\n\n    document.querySelectorAll('[data-digit]').forEach((btn) => {\n      btn.addEventListener('click', () => {\n        inputDigit(state, btn.getAttribute('data-digit'));\n        render();\n      });\n    });\n\n    document.querySelectorAll('[data-decimal]').forEach((btn) => {\n      btn.addEventListener('click', () => {\n        inputDecimal(state);\n        render();\n      });\n    });\n\n    document.querySelectorAll('[data-operator]').forEach((btn) => {\n      btn.addEventListener('click', () => {\n        chooseOperator(state, btn.getAttribute('data-operator'));\n        render();\n      });\n    });\n\n    document.querySelectorAll('[data-action]').forEach((btn) => {\n      btn.addEventListener('click', () => {\n        const action = btn.getAttribute('data-action');\n        if (action === 'clear') {\n          clearState(state);\n        } else if (action === 'backspace') {\n          backspace(state);\n        } else if (action === 'equals') {\n          computeEquals(state);\n        }\n        render();\n      });\n    });\n\n    window.addEventListener('keydown', (event) => {\n      if (shouldDeferToButtonActivation(event.target, event.key)) {\n        return;\n      }\n      handleKey(state, event.key);\n      render();\n    });\n\n    if (themeToggleEl) {\n      themeToggleEl.addEventListener('click', () => {\n        toggleTheme(document, window.localStorage);\n      });\n    }\n\n    initTheme(document, window.localStorage);\n    render();\n  })();\n}\n\nif (typeof module !== 'undefined' && module.exports) {\n  module.exports = {\n    createState,\n    inputDigit,\n    inputDecimal,\n    clearState,\n    backspace,\n    chooseOperator,\n    computeEquals,\n    getDisplayValue,\n    calculate,\n    formatNumber,\n    handleKey,\n    mapKeyToOperator,\n    shouldDeferToButtonActivation,\n    THEME_STORAGE_KEY,\n    getStoredTheme,\n    applyTheme,\n    setTheme,\n    toggleTheme,\n    initTheme,\n  };\n}\n"}, {"path": "test/calculator.test.js", "action": "modify", "content": "'use strict';\n\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst calculator = require('../src/calculator.js');\n\nconst {\n  createState,\n  inputDigit,\n  inputDecimal,\n  clearState,\n  backspace,\n  chooseOperator,\n  computeEquals,\n  getDisplayValue,\n  handleKey,\n  shouldDeferToButtonActivation,\n  THEME_STORAGE_KEY,\n  getStoredTheme,\n  toggleTheme,\n  initTheme,\n} = calculator;\n\nfunction enterDigits(state, digits) {\n  for (const ch of digits) {\n    if (ch === '.') {\n      inputDecimal(state);\n    } else {\n      inputDigit(state, ch);\n    }\n  }\n  return state;\n}\n\nfunction createFakeStorage() {\n  const data = new Map();\n  return {\n    getItem(key) {\n      return data.has(key) ? data.get(key) : null;\n    },\n    setItem(key, value) {\n      data.set(key, String(value));\n    },\n    removeItem(key) {\n      data.delete(key);\n    },\n  };\n}\n\nfunction createFakeDocument() {\n  const attributes = new Map();\n  return {\n    documentElement: {\n      setAttribute(name, value) {\n        attributes.set(name, value);\n      },\n      getAttribute(name) {\n        return attributes.has(name) ? attributes.get(name) : null;\n      },\n    },\n  };\n}\n\ntest('digit entry appends digits to the display', () => {\n  const state = createState();\n  enterDigits(state, '123');\n  assert.equal(getDisplayValue(state), '123');\n});\n\ntest('leading zero is replaced by the first digit entered', () => {\n  const state = createState();\n  inputDigit(state, '5');\n  assert.equal(getDisplayValue(state), '5');\n});\n\ntest('decimal point entry is accepted and computed correctly', () => {\n  const state = createState();\n  enterDigits(state, '2.5');\n  chooseOperator(state, '+');\n  enterDigits(state, '1.5');\n  computeEquals(state);\n  assert.equal(getDisplayValue(state), '4');\n});\n\ntest('a second decimal point in the same number is rejected', () => {\n  const state = createState();\n  enterDigits(state, '1.2');\n  inputDecimal(state);\n  inputDigit(state, '3');\n  assert.equal(getDisplayValue(state), '1.23');\n});\n\ntest('addition computes the correct result on equals', () => {\n  const state = createState();\n  enterDigits(state, '2');\n  chooseOperator(state, '+');\n  enterDigits(state, '3');\n  computeEquals(state);\n  assert.equal(getDisplayValue(state), '5');\n});\n\ntest('subtraction computes the correct result on equals', () => {\n  const state = createState();\n  enterDigits(state, '10');\n  chooseOperator(state, '-');\n  enterDigits(state, '4');\n  computeEquals(state);\n  assert.equal(getDisplayValue(state), '6');\n});\n\ntest('multiplication computes the correct result on equals', () => {\n  const state = createState();\n  enterDigits(state, '6');\n  chooseOperator(state, '×');\n  enterDigits(state, '7');\n  computeEquals(state);\n  assert.equal(getDisplayValue(state), '42');\n});\n\ntest('division computes the correct result on equals', () => {\n  const state = createState();\n  enterDigits(state, '9');\n  chooseOperator(state, '÷');\n  enterDigits(state, '2');\n  computeEquals(state);\n  assert.equal(getDisplayValue(state), '4.5');\n});\n\ntest('division by zero is handled without throwing', () => {\n  const state = createState();\n  enterDigits(state, '5');\n  chooseOperator(state, '÷');\n  enterDigits(state, '0');\n  assert.doesNotThrow(() => computeEquals(state));\n  assert.equal(getDisplayValue(state), 'Error');\n});\n\ntest('clear resets the entry, pending operator, and stored operand', () => {\n  const state = createState();\n  enterDigits(state, '99');\n  chooseOperator(state, '+');\n  enterDigits(state, '1');\n  clearState(state);\n  assert.equal(getDisplayValue(state), '0');\n  assert.equal(state.operator, null);\n  assert.equal(state.previous, null);\n});\n\ntest('backspace removes the most recently entered character', () => {\n  const state = createState();\n  enterDigits(state, '123');\n  backspace(state);\n  assert.equal(getDisplayValue(state), '12');\n});\n\ntest('backspace on a single digit resets the entry to zero', () => {\n  const state = createState();\n  inputDigit(state, '7');\n  backspace(state);\n  assert.equal(getDisplayValue(state), '0');\n});\n\ntest('equals computes the pending calculation', () => {\n  const state = createState();\n  enterDigits(state, '8');\n  chooseOperator(state, '-');\n  enterDigits(state, '3');\n  computeEquals(state);\n  assert.equal(getDisplayValue(state), '5');\n});\n\ntest('keyboard digit and operator keys behave like the on-screen buttons', () => {\n  const state = createState();\n  handleKey(state, '4');\n  handleKey(state, '2');\n  handleKey(state, '+');\n  handleKey(state, '8');\n  handleKey(state, 'Enter');\n  assert.equal(getDisplayValue(state), '50');\n});\n\ntest('Enter triggers the same computation as the equals control', () => {\n  const state = createState();\n  enterDigits(state, '6');\n  chooseOperator(state, '×');\n  enterDigits(state, '3');\n  handleKey(state, 'Enter');\n  assert.equal(getDisplayValue(state), '18');\n});\n\ntest('Backspace key triggers the same deletion as the backspace control', () => {\n  const state = createState();\n  enterDigits(state, '456');\n  handleKey(state, 'Backspace');\n  assert.equal(getDisplayValue(state), '45');\n});\n\ntest('Escape key triggers the same reset as the clear control', () => {\n  const state = createState();\n  enterDigits(state, '456');\n  chooseOperator(state, '+');\n  handleKey(state, 'Escape');\n  assert.equal(getDisplayValue(state), '0');\n  assert.equal(state.operator, null);\n});\n\ntest('theme toggle persists the selected theme across a simulated reload', () => {\n  const storage = createFakeStorage();\n  const firstLoadDocument = createFakeDocument();\n\n  const initialTheme = initTheme(firstLoadDocument, storage);\n  assert.equal(initialTheme, 'light');\n\n  const toggled = toggleTheme(firstLoadDocument, storage);\n  assert.equal(toggled, 'dark');\n  assert.equal(getStoredTheme(storage), 'dark');\n\n  const secondLoadDocument = createFakeDocument();\n  const restoredTheme = initTheme(secondLoadDocument, storage);\n\n  assert.equal(restoredTheme, 'dark');\n  assert.equal(secondLoadDocument.documentElement.getAttribute('data-theme'), 'dark');\n});\n\ntest('theme storage key is stable', () => {\n  assert.equal(THEME_STORAGE_KEY, 'calculator-theme');\n});\n\ntest('pressing Enter while a focused on-screen button would activate defers to the button click', () => {\n  const buttonTarget = { tagName: 'BUTTON' };\n  assert.equal(shouldDeferToButtonActivation(buttonTarget, 'Enter'), true);\n  assert.equal(shouldDeferToButtonActivation(buttonTarget, ' '), true);\n});\n\ntest('global key handling still applies when no button is focused', () => {\n  const bodyTarget = { tagName: 'BODY' };\n  assert.equal(shouldDeferToButtonActivation(bodyTarget, 'Enter'), false);\n  assert.equal(shouldDeferToButtonActivation(null, 'Enter'), false);\n});\n\ntest('deferral only applies to native button-activation keys, not Backspace or Escape', () => {\n  const buttonTarget = { tagName: 'BUTTON' };\n  assert.equal(shouldDeferToButtonActivation(buttonTarget, 'Backspace'), false);\n  assert.equal(shouldDeferToButtonActivation(buttonTarget, 'Escape'), false);\n});\n\ntest('tabbing to Backspace and pressing Enter does not collapse a pending calculation via computeEquals', () => {\n  const state = createState();\n  enterDigits(state, '5');\n  chooseOperator(state, '+');\n  enterDigits(state, '23');\n\n  const backspaceButtonFocused = { tagName: 'BUTTON' };\n  if (!shouldDeferToButtonActivation(backspaceButtonFocused, 'Enter')) {\n    handleKey(state, 'Enter');\n  }\n  backspace(state);\n\n  assert.equal(getDisplayValue(state), '2');\n});\n"}]}]}
